'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const regions=['Pseudocapsule','Periphery','Core','Myometrium'];
let state={participants:[],view:'participants',selected:null,region:'Pseudocapsule',qtab:'appendix'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=1)=>v==null?'—':Number(v).toFixed(d);
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000)}
async function api(path,body){return PagesStore.request(path,body)}
function participant(){return state.participants.find(p=>p.id===state.selected)}
function heading(k,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function dashboard(){const n=state.participants.length;$('#app').innerHTML=heading('STUDY OVERVIEW','Participants','Zonal fibrosis, vitamin D and patient-reported outcomes.','<button class="button primary" id="new-participant">＋ Add participant</button>')+`<div class="metrics"><div class="metric"><div class="label">Participants enrolled</div><div class="value">${n} <span class="muted" style="font-size:16px">/ 32</span></div><small>Protocol recruitment target</small><div class="progress"><div style="width:${Math.min(100,n/32*100)}%"></div></div></div><div class="metric"><div class="label">Four-region measurements</div><div class="value" id="complete-count">0</div><small>Participants with all regions</small></div><div class="metric"><div class="label">Questionnaire records</div><div class="value" id="question-count">0</div><small>PBAC and UFS-QOL recorded</small></div><div class="metric"><div class="label">Primary association</div><div class="value" style="font-size:22px">Vitamin D × fibrosis</div><small>Pseudocapsule collagen fraction</small></div></div><section class="card"><div class="card-title"><h2>Study register</h2><span class="badge">${n} participant${n===1?'':'s'}</span></div>${n?`<div class="table-wrap"><table><thead><tr><th>STUDY ID</th><th>AGE</th><th>VITAMIN D</th><th>TISSUE REGIONS</th><th>LAST SAVED</th><th></th></tr></thead><tbody>${state.participants.map(p=>`<tr><td><strong>${esc(p.id)}</strong></td><td>${esc(p.age??'—')}</td><td>${fmt(p.vitaminD)} ng/mL</td><td>${regions.filter(r=>(p.measurements||[]).some(m=>m.region===r)).length} / 4</td><td>${p.updated?new Date(p.updated).toLocaleDateString():'—'}</td><td><button class="button small open-participant" data-id="${esc(p.id)}">Open record</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-mark">＋</div><h3>Your study starts with one participant</h3><p>Add a study ID, then record tissue measurements and questionnaire responses.</p><button class="button primary" id="empty-add">Add first participant</button></div>`}</section><div class="two-col"><section class="card"><div class="card-title"><h2>Four regions. One participant.</h2><span class="badge pink">Masson’s Trichrome</span></div>${regions.map((r,i)=>`<div class="region-line"><span><span class="region-num">0${i+1}</span>${r}</span><span class="muted small-text">${i===0?'Primary outcome':i===3?'Control tissue':'Paired measurement'}</span></div>`).join('')}</section><section class="card"><h2>A traceable research workflow</h2><p>Upload and review slide images, or enter existing percentages. Keep each field linked to its tissue region.</p><div class="note">Image measurements are preliminary until calibrated against pathologist-reviewed slides.</div><button class="button ghost" id="view-methods">View study methods</button></section></div>`;$('#new-participant').onclick=openNew;$('#empty-add')?.addEventListener('click',openNew);$('#view-methods').onclick=()=>navigate('methods');$$('.open-participant').forEach(b=>b.onclick=()=>{state.selected=b.dataset.id;navigate('tissue')})}
function openNew(){$('#participant-form').reset();$('#participant-dialog').showModal()}
function leaveDraft(){if(state.dirty&&!confirm('Leave this page and discard unsaved entries?'))return false;state.dirty=false;return true}
function navigate(view){if(!leaveDraft())return;imageState=null;state.view=view;window.scrollTo(0,0);$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent='Study / '+({participants:'Participants',tissue:'Tissue workspace',questionnaires:'Questionnaires',analysis:'Study analysis',methods:'Methods & backup'}[view]);render()}
function render(){({participants:dashboard,tissue:tissue,questionnaires:questionnaires,analysis:analysisPage,methods:methodsPage}[state.view])();if(state.view==='participants'){ $('#complete-count').textContent=state.participants.filter(p=>regions.every(r=>aggregate(p,r))).length;$('#question-count').textContent=state.participants.filter(p=>p.pbac?.result?.score!=null&&(p.appendixD?.result?.composite!=null||(p.ufs?.confirmed&&p.ufs?.result?.domains?.['HRQL total']?.score!=null))).length}}
$$('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#close-participant').onclick=()=>$('#participant-dialog').close();$('#participant-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);const id=f.get('id').trim();if(state.participants.some(p=>p.id===id))throw Error('This study ID already exists.');const p={id,age:f.get('age')===''?null:+f.get('age'),vitaminD:f.get('vitaminD')===''?null:+f.get('vitaminD'),measurements:[]};await api('participants',p);state.participants=await api('participants');state.selected=id;$('#participant-dialog').close();render();toast('Participant saved')}catch(e){toast(e.message)}};
api('participants').then(p=>{state.participants=p;state.selected=p[0]?.id;render()}).catch(e=>{$('#app').innerHTML='<div class="note warning">'+esc(e.message)+'</div>'});

// Local drafts are never authoritative; saved records live in the local database.
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});
$('#backup-top').onclick=()=>downloadURL('/api/backup');
function downloadURL(url){PagesStore.exportFile(url.replace('/api/','')).catch(e=>toast(e.message))}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function dirty(){state.dirty=true;$('#save-state').textContent='Unsaved changes'}
function num(v){return v===''?null:Number(v)}
async function save(p){const saved=await api('participants',p);const i=state.participants.findIndex(x=>x.id===saved.id);if(i>=0)state.participants[i]=saved;else state.participants.push(saved);state.dirty=false;$('#save-state').textContent='Saved on this computer';state.report=null;toast('Record saved');return saved}
function aggregate(p,region,reviewer='A'){const m=(p.measurements||[]).filter(x=>x.region===region&&x.reviewer===reviewer);if(!m.length)return null;const weighted=m.every(x=>x.eligible>0);const total=m.reduce((s,x)=>s+(weighted?x.eligible:1),0);return {blue:m.reduce((s,x)=>s+x.blue*(weighted?x.eligible:1),0)/total,pink:m.reduce((s,x)=>s+x.pink*(weighted?x.eligible:1),0)/total,n:m.length,weighted}}
function selectParticipant(){return `<div class="toolbar"><label>Participant<select id="participant-select">${state.participants.map(p=>`<option value="${esc(p.id)}" ${p.id===state.selected?'selected':''}>${esc(p.id)}</option>`).join('')}</select></label></div>`}
function bindParticipant(){const el=$('#participant-select');if(el)el.onchange=()=>{if(!leaveDraft()){el.value=state.selected;return}state.selected=el.value;imageState=null;render()}}
function needParticipant(){if(!state.participants.length){$('#app').innerHTML=heading('STUDY RECORDS','Add a participant first','Measurements and responses are always linked to a study ID.')+'<button class="button primary" id="add-required">Add participant</button>';$('#add-required').onclick=openNew;return true}if(!participant())state.selected=state.participants[0].id;return false}
function input(label,name,value='',type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`}
function options(values,selected){return values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v||'Not recorded')}</option>`).join('')}
function clinicalForm(p){return `<details class="card"><summary>Clinical record · ${esc(p.id)}</summary><p class="small-text" style="margin-top:12px">Enter study data only. Do not include names or hospital identifiers.</p><form id="clinical-form"><div class="form-grid">${input('Age (years)','age',p.age,'number','min="25" max="55" step="1"')}${input('Serum vitamin D (ng/mL)','vitaminD',p.vitaminD,'number','min="0" max="1000" step="0.01"')}${input('Parity','parity',p.parity,'number','min="0" max="30" step="1"')}${input('BMI (kg/m²)','bmi',p.bmi,'number','min="5" max="100" step="0.01"')}${input('Haemoglobin (g/dL)','hemoglobin',p.hemoglobin,'number','min="0" max="30" step="0.01"')}${input('Largest fibroid dimension (cm)','size',p.size,'number','min="0" max="100" step="0.01"')}${input('Second perpendicular dimension (cm)','width',p.width,'number','min="0" max="100" step="0.01"')}${input('Third perpendicular dimension (cm)','depth',p.depth,'number','min="0" max="100" step="0.01"')}<label>Fibroid location<select name="location">${options(['','Submucosal','Intramural','Subserosal','Other'],p.location)}</select></label><label>Multiplicity<select name="multiplicity">${options(['','Single','Multiple'],p.multiplicity)}</select></label>${input('Enrolment date','enrolment',p.enrolment,'date')}<label>Study notes<textarea name="notes" maxlength="5000">${esc(p.notes||'')}</textarea></label></div><p class="small-text">If all three dimensions are entered, volume is estimated as π/6 × length × width × depth.</p><button class="button primary">Save clinical record</button></form></details>`}
function bindClinical(){
 const f=$('#clinical-form');if(!f)return;
 const panel=f.closest('details');let editing=false;
 const cancel=document.createElement('button');cancel.type='button';cancel.className='button ghost';cancel.style.marginLeft='10px';cancel.textContent='Cancel clinical edits';f.append(cancel);
 panel.addEventListener('toggle',()=>{
   if(panel.open){
     if(state.dirty&&!editing){panel.open=false;toast('Save your field entries before opening the clinical record.');return}
     editing=true;
   }else{
     if(editing&&state.dirty){panel.open=true;toast('Save clinical changes or use Cancel clinical edits.');return}
     editing=false;
   }
   const work=$('.work-grid');if(work)work.inert=panel.open;
 });
 cancel.onclick=()=>{f.reset();state.dirty=false;$('#save-state').textContent='Local research workspace';panel.open=false};
 f.oninput=dirty;
 f.onsubmit=async e=>{e.preventDefault();try{const p=structuredClone(participant());for(const [k,v]of new FormData(f))p[k]=['age','vitaminD','parity','bmi','hemoglobin','size','width','depth'].includes(k)?num(v):v;await save(p);render()}catch(e){toast(e.message)}}
}
let imageState=null;
function tissue(){if(needParticipant())return;const p=participant();const reviewer=state.reviewer||'A';const m=(p.measurements||[]).filter(m=>m.region===state.region);const agg=aggregate(p,state.region,reviewer);$('#app').innerHTML=heading('HISTOMORPHOMETRY','Tissue workspace','Review each field. Keep its region and reviewer attached.')+selectParticipant()+`<div class="toolbar"><label class="checkbox-label"><input id="blind" type="checkbox" ${state.blind?'checked':''}>Hide clinical data during review</label></div>`+(state.blind?'':clinicalForm(p))+`<div class="tabs" role="group" aria-label="Tissue region">${regions.map(r=>`<button class="tab ${r===state.region?'active':''}" data-region="${r}">${r}</button>`).join('')}</div><div class="work-grid"><section class="card"><div class="card-title"><h2>${state.region}</h2><span class="badge">${esc(p.id)}</span></div><div class="tabs"><button class="tab ${state.mode!=='image'?'active':''}" data-mode="manual">Enter percentages</button><button class="tab ${state.mode==='image'?'active':''}" data-mode="image">Analyse an image</button></div>${state.mode==='image'?imageForm():manualForm()}</section><aside><section class="card"><h3>Region summary</h3><p class="small-text">Reviewer ${reviewer} · ${agg?.n||0} saved field${agg?.n===1?'':'s'}</p><div class="result-values"><div><span class="blue">Blue collagen</span><strong>${fmt(agg?.blue)}%</strong></div><div><span class="pink-text">Pink tissue</span><strong>${fmt(agg?.pink)}%</strong></div></div><p class="small-text" style="margin-top:15px">${agg?(agg.weighted?'Weighted by eligible tissue area.':'Equal field weights: pixel areas are unavailable.'):'Save a field to calculate this region’s result.'}</p></section><section class="card"><h3>Measurement definition</h3><p class="small-text">Blue or pink pixels ÷ eligible tissue pixels × 100.</p><p class="small-text">Other tissue stays in the denominator. White background and marked exclusions do not.</p><span class="badge amber">Pilot validation required</span></section></aside></div><section class="card"><div class="card-title"><h2>Saved fields</h2><span class="badge">${m.length} measurements</span></div>${m.length?`<div class="table-wrap"><table><thead><tr><th>FIELD</th><th>REVIEWER</th><th>SOURCE</th><th>BLUE %</th><th>PINK %</th><th>TISSUE PIXELS</th><th></th></tr></thead><tbody>${m.map(x=>`<tr><td>${esc(x.field)}</td><td>${x.reviewer}</td><td>${x.source==='image'?'Image · reviewed':'Manual'}</td><td class="blue">${fmt(x.blue,2)}</td><td class="pink-text">${fmt(x.pink,2)}</td><td>${x.eligible?.toLocaleString()||'Not supplied'}</td><td><div class="row-actions">${x.asset?`<a class="button small" href="${PagesStore.assetURL(x.asset+'.overlay.png')}" target="_blank" rel="noopener">Overlay</a><a class="button small" href="${PagesStore.assetURL(x.asset+'.mask.png')}" download>Mask</a>`:''}<button class="button small danger remove-measurement" data-mid="${esc(x.id)}">Remove</button></div></td></tr>`).join('')}</tbody></table></div>`:'<p>No fields saved for this region.</p>'}</section>`;bindParticipant();bindClinical();$('#blind').onchange=e=>{if(leaveDraft()){state.blind=e.target.checked;render()}};$$('[data-region]').forEach(b=>b.onclick=()=>{if(leaveDraft()){state.region=b.dataset.region;imageState=null;render()}});$$('[data-mode]').forEach(b=>b.onclick=()=>{if(leaveDraft()){state.mode=b.dataset.mode;render()}});$$('.remove-measurement').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this measurement? Its previous value remains in the backup audit history.'))return;try{const p=structuredClone(participant());p.measurements=p.measurements.filter(m=>m.id!==b.dataset.mid);await save(p);render()}catch(e){toast(e.message)}});if(state.mode==='image')bindImage();else bindManual()}
function measurementIdentity(){return `<div class="form-grid">${input('Field ID','field','','text','required maxlength="100" placeholder="e.g. slide-1-field-1"')}<label>Pathologist / reviewer<select name="reviewer">${options(['A','B'],state.reviewer||'A')}</select></label></div>`}
function manualForm(){return `<form id="manual-form">${measurementIdentity()}<div class="form-grid">${input('Blue collagen (%)','blue','','number','required min="0" max="100" step="0.0001"')}${input('Pink tissue (%)','pink','','number','required min="0" max="100" step="0.0001"')}</div>${input('Eligible tissue pixel count (optional)','eligible','','number','min="1" step="1"')}<p class="small-text">Enter percentages of all eligible tissue. Use consistent, non-overlapping fields. Supply the pixel count if available for area-weighted aggregation.</p><button class="button primary">Save field measurement</button></form>`}
function bindManual(){const f=$('#manual-form');f.oninput=dirty;f.onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(f));const p=structuredClone(participant());p.measurements.push({id:crypto.randomUUID(),region:state.region,reviewer:d.reviewer,field:d.field.trim(),blue:num(d.blue),pink:num(d.pink),eligible:num(d.eligible),source:'manual',created:new Date().toISOString()});await save(p);state.reviewer=d.reviewer;render()}catch(e){toast(e.message)}}}
const defaultThresholds={background:245,saturation:35,dark:25,blueLow:170,blueHigh:270,pinkLow:285,pinkHigh:25};
function imageForm(){return `<form id="image-form">${measurementIdentity()}<label>Slide field image<input id="image-file" type="file" accept="image/png,image/jpeg,image/tiff,.tif,.tiff"></label><p class="small-text">JPEG, PNG or single-page TIFF · up to 20 megapixels / 30 MB. Whole-slide formats must be exported as fields.</p><div class="canvas-tools"><select id="draw-mode" aria-label="Selection tool" style="width:auto;margin:0"><option value="roi">Draw tissue rectangle</option><option value="exclude">Draw exclusion</option></select><button type="button" class="button small" id="reset-roi">Reset selection</button><button type="button" class="button small" id="toggle-overlay">Show overlay</button></div><div class="canvas-area" id="canvas-area"><div class="empty"><div class="empty-mark">↥</div><h3>Select a slide image</h3><p class="small-text">Draw a tissue rectangle and exclude unwanted areas before accepting the colour mask.</p></div></div><details><summary>Colour detection settings</summary><p class="small-text">Hue values are degrees. Pink can wrap through 0°. Background is excluded when all RGB channels meet the threshold. Dark/low-saturation tissue remains in the denominator.</p><div class="form-grid">${Object.entries(defaultThresholds).map(([k,v])=>input(({background:'White background threshold (0–255)',saturation:'Minimum colour saturation (0–255)',dark:'Minimum brightness for colour (0–255)',blueLow:'Blue hue start',blueHigh:'Blue hue end',pinkLow:'Pink hue start',pinkHigh:'Pink hue end'}[k]),k,imageState?.settings[k]??v,'number',`min="0" max="${k.includes('Low')||k.includes('High')?360:255}" required`)).join('')}</div></details><button type="button" class="button" id="analyse-image">Calculate selected area</button><div id="image-result" style="margin-top:16px"></div><label class="checkbox-label"><input id="reviewed-mask" type="checkbox" required>I reviewed the selection and colour overlay.</label><button class="button primary" id="save-image">Save reviewed measurement</button><p class="small-text" style="margin-top:12px">Colour thresholds are a preliminary research measurement. Validate them with your pathologist before thesis use.</p></form>`}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Unable to read the file'));r.readAsDataURL(file)})}
async function calculateImage(){if(!imageState)throw Error('Select an image first.');const settings={};for(const k of Object.keys(defaultThresholds))settings[k]=num($('#image-form').elements[k].value);const btn=$('#analyse-image');btn.disabled=true;btn.textContent='Measuring…';try{const result=await api('measure',{image:imageState.data,filename:imageState.filename,settings,roi:imageState.roi,excludes:imageState.excludes});imageState.result=result;imageState.settings=settings;imageState.showOverlay=true;$('#reviewed-mask').checked=false;await drawImageCanvas();showImageResult();dirty()}finally{btn.disabled=false;btn.textContent='Calculate selected area'}}
function invalidateImage(){if(imageState){imageState.result=null;imageState.showOverlay=false;$('#reviewed-mask').checked=false;$('#image-result').innerHTML='<div class="note">Selection/settings changed. Calculate again before saving.</div>';dirty()}}
function showImageResult(){const r=imageState?.result;if(!r)return;$('#image-result').innerHTML=`<div class="result-values"><div><span class="blue">Blue collagen</span><strong>${fmt(r.blue,2)}%</strong><small>${r.bluePixels.toLocaleString()} pixels</small></div><div><span class="pink-text">Pink tissue</span><strong>${fmt(r.pink,2)}%</strong><small>${r.pinkPixels.toLocaleString()} pixels</small></div></div><p class="small-text" style="margin-top:12px">${r.eligible.toLocaleString()} eligible tissue pixels · ${fmt(100-r.blue-r.pink,2)}% other tissue · original ${r.width} × ${r.height}px</p>`}
async function drawImageCanvas(){if(!imageState)return;const s=imageState;const src=s.result?PagesStore.assetURL(s.result.asset+(s.showOverlay?'.overlay':'')+'.png'):s.preview; if(!src)return;const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('Cannot display this image.'));img.src=src});if(imageState!==s)return;s.preview=s.result?PagesStore.assetURL(s.result.asset+'.png'):s.preview;const area=$('#canvas-area');if(!area)return;area.innerHTML='<canvas id="slide-canvas" aria-label="Tissue region selection. Drag to select or exclude a rectangle."></canvas>';const c=$('#slide-canvas');const scale=Math.min(1,1100/img.width);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');const paint=()=>{ctx.drawImage(img,0,0,c.width,c.height);ctx.lineWidth=2;for(const [r,color]of [[s.roi,'#148a7b'],...s.excludes.map(r=>[r,'#de412b'])])if(r){ctx.strokeStyle=color;ctx.strokeRect(r[0]*c.width,r[1]*c.height,(r[2]-r[0])*c.width,(r[3]-r[1])*c.height)}};paint();let start=null;const pos=e=>{const b=c.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))]};c.onpointerdown=e=>{start=pos(e);c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!start)return;const end=pos(e);paint();ctx.strokeStyle='#efab23';ctx.strokeRect(start[0]*c.width,start[1]*c.height,(end[0]-start[0])*c.width,(end[1]-start[1])*c.height)};c.onpointerup=e=>{if(!start)return;const end=pos(e);const r=[Math.min(start[0],end[0]),Math.min(start[1],end[1]),Math.max(start[0],end[0]),Math.max(start[1],end[1])];start=null;if(r[2]-r[0]<.005||r[3]-r[1]<.005){paint();return}if($('#draw-mode').value==='roi')s.roi=r;else s.excludes.push(r);invalidateImage();drawImageCanvas()};$('#toggle-overlay').textContent=s.showOverlay?'Show original':'Show overlay'}
function bindImage(){const f=$('#image-form');f.oninput=e=>{dirty();if(Object.keys(defaultThresholds).includes(e.target.name))invalidateImage()};$('#image-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>30e6)throw Error('Choose an image under 30 MB.');imageState={data:await fileData(file),filename:file.name,roi:null,excludes:[],settings:{...defaultThresholds},result:null};await calculateImage()}catch(e){toast(e.message)}};$('#analyse-image').onclick=()=>calculateImage().catch(e=>toast(e.message));$('#reset-roi').onclick=()=>{if(!imageState)return;imageState.roi=null;imageState.excludes=[];invalidateImage();drawImageCanvas()};$('#toggle-overlay').onclick=()=>{if(!imageState?.result)return toast('Calculate the area first.');imageState.showOverlay=!imageState.showOverlay;drawImageCanvas()};f.onsubmit=async e=>{e.preventDefault();try{if(!imageState?.result)throw Error('Calculate the current image selection first.');if(!$('#reviewed-mask').checked)throw Error('Review the overlay before saving.');const d=Object.fromEntries(new FormData(f));const p=structuredClone(participant());p.measurements.push({...imageState.result,id:crypto.randomUUID(),region:state.region,field:d.field.trim(),reviewer:d.reviewer,reviewed:true,created:new Date().toISOString()});await save(p);state.reviewer=d.reviewer;imageState=null;render()}catch(e){toast(e.message)}};if(imageState){drawImageCanvas();showImageResult()}}

const domainMap={'Symptom severity':[1,2,3,4,5,6,7,8],'Concern':[9,15,22,28,32],'Activities':[10,11,13,19,20,27,29],'Energy / mood':[12,17,23,24,25,31,35],'Control':[14,16,26,30,34],'Self-consciousness':[18,21,33],'Sexual function':[36,37]};
function questionnaires(){if(needParticipant())return;$('#app').innerHTML=heading('PATIENT-REPORTED OUTCOMES','Questionnaires','Record a cycle diary and questionnaire responses for each participant.')+selectParticipant()+`<div class="tabs"><button class="tab ${state.qtab==='appendix'?'active':''}" data-qtab="appendix">Appendix D questionnaire</button><button class="tab ${state.qtab==='pbac'?'active':''}" data-qtab="pbac">PBAC diary</button><button class="tab ${state.qtab==='ufs'?'active':''}" data-qtab="ufs">UFS-QOL scoring</button></div><div id="question-content"></div>`;bindParticipant();$$('[data-qtab]').forEach(b=>b.onclick=()=>{if(leaveDraft()){state.qtab=b.dataset.qtab;render()}});if(state.qtab==='pbac')pbacForm();else if(state.qtab==='appendix')appendixForm();else ufsForm()}
function pbacForm(){const b=participant().pbac||{};const days=b.days||Array.from({length:31},()=>Array(9).fill(null));const cols=['Pad light<br>×1','Pad medium<br>×5','Pad heavy<br>×20','Tampon light<br>×1','Tampon medium<br>×5','Tampon heavy<br>×10','Small clot<br>×1','Large clot<br>×5','Flooding<br>×1'];$('#question-content').innerHTML=`<section class="card"><div class="card-title"><h2>Menstrual-cycle diary</h2><span class="badge">Protocol threshold: &gt;100</span></div><p>Enter counts for each recorded day. Use “Zero blanks” to confirm unused categories as zero. Leave unrecorded days blank.</p><form id="pbac-form">${input('Cycle start date','start',b.start,'date','required')}<div class="table-wrap" style="max-height:450px"><table class="pbac"><thead><tr><th>Cycle day</th>${cols.map(c=>`<th>${c}</th>`).join('')}<th>Subtotal</th><th></th></tr></thead><tbody>${days.map((row,i)=>`<tr><td>${i+1}</td>${row.map((v,j)=>`<td><input type="number" min="0" max="10000" step="1" aria-label="Day ${i+1}, ${cols[j].replace('<br>',' ')}" data-day="${i}" data-col="${j}" value="${v??''}"></td>`).join('')}<td id="day-total-${i}">—</td><td><button class="button small zero-row" type="button" data-row="${i}">Zero blanks</button></td></tr>`).join('')}</tbody></table></div><div class="note">The supplied chart assigns flooding 1 point. Clot pictures use “5 cent” and “50 cent” references; use your agreed chart for size classification.</div><label class="checkbox-label"><input name="complete" type="checkbox" ${b.complete?'checked':''}>I confirm all days of this menstrual cycle are accounted for; blank rows are outside the recorded cycle.</label><div id="pbac-score" class="scores"></div><button class="button primary" style="margin-top:18px">Save PBAC diary</button></form></section>`;const f=$('#pbac-form');const read=()=>({days:days.map((_,i)=>$$(`[data-day="${i}"]`).map(x=>num(x.value))),start:f.elements.start.value,complete:f.elements.complete.checked});let timer;const calc=async()=>{try{const r=await api('score/pbac',read());if(!$('#pbac-score'))return;r.daily.forEach((v,i)=>{const el=$('#day-total-'+i);if(el)el.textContent=v??'—'});$('#pbac-score').innerHTML=`<div class="score-box"><span>Recorded subtotal</span><strong>${r.subtotal}</strong></div><div class="score-box"><span>Final cycle score</span><strong>${r.score??'Incomplete'}</strong></div><div class="score-box"><span>Study classification</span><strong style="font-size:18px">${r.score==null?'Awaiting completion':r.heavyBleeding?'PBAC >100':'PBAC ≤100'}</strong></div>${r.incompleteRows?'<p class="note warning">Some recorded days contain blank categories. Confirm their counts before final scoring.</p>':''}`}catch(e){toast(e.message)}};f.oninput=()=>{dirty();clearTimeout(timer);timer=setTimeout(calc,250)};$$('.zero-row').forEach(b=>b.onclick=()=>{$$(`[data-day="${b.dataset.row}"]`).forEach(i=>{if(i.value==='')i.value='0'});dirty();calc()});f.onsubmit=async e=>{e.preventDefault();try{const p=structuredClone(participant());p.pbac=read();await save(p);render()}catch(e){toast(e.message)}};calc()}
function ufsForm(){const u=participant().ufs||{};const a=u.answers||Array(37).fill(null);$('#question-content').innerHTML=`<section class="card"><div class="card-title"><h2>Official UFS-QOL response scoring</h2><span class="badge">37 items · 0–100 scores</span></div><div class="note">Transcribe item numbers from your authorized official questionnaire. The questionnaire wording is not included here. Use the Appendix D tab for the supplied study questionnaire and its separate raw-sum scores.</div><p class="small-text"><a href="https://eprovide.mapi-trust.org/instruments/uterine-fibroid-symptom-and-health-related-quality-of-life-questionnaire" target="_blank" rel="noopener">Request the official form</a> · <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10071864/" target="_blank" rel="noopener">Published scoring manual, Appendix B</a></p><form id="ufs-form"><div class="form-grid">${input('Assessment date','date',u.date,'date','required')}<label>Official form recall period<select name="recall"><option value="3 months" ${u.recall!=='1 month'?'selected':''}>3 months — original</option><option value="1 month" ${u.recall==='1 month'?'selected':''}>1 month — authorized 37-item version</option></select></label></div><p class="small-text">This calculator uses the original six-domain mapping. It does not calculate the separate Revised Activities subscale.</p><div class="question-grid">${a.map((v,i)=>`<label>Item ${i+1}<select data-item="${i}" aria-label="UFS-QOL item ${i+1}"><option value="">Unanswered</option>${[1,2,3,4,5].map(n=>`<option ${v===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><label class="checkbox-label" style="margin-top:18px"><input name="confirmed" type="checkbox" ${u.confirmed?'checked':''}>Responses come from the authorized official form, with the original item numbering and six-domain mapping.</label><div id="ufs-scores" class="scores"></div><p class="small-text" style="margin-top:16px">Higher symptom severity = worse symptoms. Higher HRQL = better quality of life. With fewer than half the items missing within a scale, missing items use the participant’s mean of answered items in that scale. Otherwise that scale is unavailable; a missing HRQL domain prevents the total.</p><button class="button primary">Save UFS-QOL responses</button><details><summary>Item mapping and scoring</summary>${Object.entries(domainMap).map(([k,v])=>`<p class="small-text"><strong>${k}:</strong> ${v.join(', ')}</p>`).join('')}<p class="small-text">Symptom severity: (raw − 8) / 32 × 100. HRQL total: (145 − sum of raw HRQL domain scores) / 116 × 100. Domain scores use the analogous range for their item count. Symptom severity is never added to HRQL total.</p></details></form></section>`;const f=$('#ufs-form');const read=()=>({answers:$$('[data-item]').map(x=>num(x.value)),date:f.elements.date.value,recall:f.elements.recall.value,confirmed:f.elements.confirmed.checked});let timer;const calc=async()=>{try{const r=await api('score/ufs',read());if(!$('#ufs-scores'))return;$('#ufs-scores').innerHTML=Object.entries(r.domains).map(([k,v])=>`<div class="score-box"><span class="small-text">${k}</span><strong>${fmt(v.score)}</strong><span class="small-text muted">${v.answered}/${v.items} answered${v.imputed?' · '+v.imputed+' imputed':''}</span></div>`).join('')+(!r.confirmed?'<div class="note warning">Preview only. Confirm the official form before these scores enter study analyses.</div>':'')}catch(e){toast(e.message)}};f.oninput=()=>{dirty();clearTimeout(timer);timer=setTimeout(calc,200)};f.onsubmit=async e=>{e.preventDefault();try{const p=structuredClone(participant());p.ufs=read();await save(p);render()}catch(e){toast(e.message)}};calc()}

const labels={vitaminD:'Vitamin D (ng/mL)',pbac:'PBAC',bmi:'BMI',age:'Age',parity:'Parity',hemoglobin:'Haemoglobin',size:'Fibroid size (cm)',volume:'Estimated volume (cm³)',vitaminStatus:'Vitamin D status',sizeGroup:'Size group',bleedingGroup:'PBAC group',multiplicity:'Multiplicity',location:'Location'};
const label=k=>labels[k]||k;
const pval=v=>v==null?'—':v<.0001?'<0.0001':v.toFixed(4);
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function scatter(points,xlabel,ylabel){if(!points?.length)return '<p>No paired observations yet.</p>';const w=650,h=300,l=70,r=25,t=25,b=55;let xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmin===xmax){xmin-=1;xmax+=1}if(ymin===ymax){ymin-=1;ymax+=1}const pad=(ymax-ymin)*.08;ymin-=pad;ymax+=pad;const X=x=>l+(x-xmin)/(xmax-xmin)*(w-l-r),Y=y=>h-b-(y-ymin)/(ymax-ymin)*(h-t-b);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(ylabel+' versus '+xlabel)}">${[0,.25,.5,.75,1].map(f=>{const y=ymin+f*(ymax-ymin),x=xmin+f*(xmax-xmin);return `<line x1="${l}" y1="${Y(y)}" x2="${w-r}" y2="${Y(y)}" stroke="#e2eaf0"/><text x="${l-10}" y="${Y(y)+4}" text-anchor="end" font-size="12" fill="#657681">${fmt(y)}</text><text x="${X(x)}" y="${h-b+20}" text-anchor="middle" font-size="12" fill="#657681">${fmt(x)}</text>`}).join('')}${points.map(p=>`<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="4.5" fill="#217ba4" opacity=".8"><title>${esc(xlabel)}: ${fmt(p[0],2)}; ${esc(ylabel)}: ${fmt(p[1],2)}</title></circle>`).join('')}<text x="${w/2}" y="${h-8}" text-anchor="middle" font-size="13" fill="#35586b">${esc(xlabel)}</text><text transform="translate(15 ${h/2}) rotate(-90)" text-anchor="middle" font-size="13" fill="#35586b">${esc(ylabel)}</text></svg>`}
function pairedPlot(rows){const valid=rows.filter(r=>regions.every(z=>r[z]!=null));if(!valid.length)return '<p>No participants with all four regions yet.</p>';const w=650,h=280;return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Within-participant collagen fractions across four regions">${[0,25,50,75,100].map(v=>`<line x1="55" x2="620" y1="${230-v*2}" y2="${230-v*2}" stroke="#e2eaf0"/><text x="45" y="${234-v*2}" text-anchor="end" fill="#657681" font-size="12">${v}%</text>`).join('')}${valid.map(r=>`<polyline points="${regions.map((z,i)=>`${90+i*165},${230-r[z]*2}`).join(' ')}" fill="none" stroke="#5f93ae" stroke-width="1.5" opacity=".45"/>`).join('')}${regions.map((z,i)=>`<text x="${90+i*165}" y="260" text-anchor="middle" fill="#35586b" font-size="12">${z}</text>`).join('')}</svg>`}
function analysisPage(){const o=state.analysisOptions||{reviewer:'A',correlation:'spearman',zonal:'friedman',outcome:'pbac',predictors:['vitaminD']};$('#app').innerHTML=heading('THESIS STATISTICS','Study analysis','Participant-level results with explicit methods and missing-data counts.')+`<section class="card"><form id="analysis-form"><div class="form-grid"><label>Measurement reviewer<select name="reviewer">${options(['A','B'],o.reviewer)}</select></label><label>Correlation method<select name="correlation"><option value="spearman" ${o.correlation==='spearman'?'selected':''}>Spearman rank correlation</option><option value="pearson" ${o.correlation==='pearson'?'selected':''}>Pearson correlation</option></select></label><label>Four-region comparison<select name="zonal"><option value="friedman" ${o.zonal==='friedman'?'selected':''}>Friedman with Wilcoxon post-hoc</option><option value="anova" ${o.zonal==='anova'?'selected':''}>Repeated-measures ANOVA (GG corrected)</option></select></label><label>Exploratory regression outcome<select name="outcome">${['pbac','Symptom severity','HRQL total'].map(k=>`<option value="${k}" ${o.outcome===k?'selected':''}>${label(k)}</option>`).join('')}</select></label></div><details><summary>Regression predictors</summary><div class="form-grid">${['vitaminD','age','bmi','parity','size','Pseudocapsule'].map(k=>`<label class="checkbox-label"><input type="checkbox" name="predictor" value="${k}" ${o.predictors.includes(k)?'checked':''}>${label(k)}</label>`).join('')}</div></details><p class="small-text">Choose methods using your agreed analysis plan and diagnostic plots. Normality checks alone do not select the test. Reviewer A and B are analysed separately; they are never counted as separate participants.</p><button class="button primary" id="run-analysis">Run analysis</button></form></section><div id="analysis-result">${state.report?'':'<section class="card empty"><h3>Ready when your data are</h3><p>Run an analysis to see available results and the measurements still needed.</p></section>'}</div>`;$('#analysis-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const o={reviewer:f.get('reviewer'),correlation:f.get('correlation'),zonal:f.get('zonal'),outcome:f.get('outcome'),predictors:f.getAll('predictor')};if(!o.predictors.length)return toast('Select at least one regression predictor.');const b=$('#run-analysis');b.disabled=true;b.textContent='Calculating…';try{state.report=await api('analysis',o);state.analysisOptions=o;state.report.generated=new Date().toISOString();renderReport()}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Run analysis'}};if(state.report)renderReport()}
function renderReport(){const r=state.report;if(!$('#analysis-result'))return;const primary=r.correlations[0],z=r.zonal,g=r.regression;$('#analysis-result').innerHTML=`<div class="toolbar"><button class="button" id="print-report">Print / save PDF</button><button class="button" id="export-analysis">Export full results</button><button class="button" id="export-master">Export master CSV</button><button class="button" id="export-charts">Download charts</button></div><p class="small-text">${r.n} participants · Reviewer ${r.reviewer} · ${new Date(r.generated).toLocaleString()} · calculation version ${r.version}</p>${r.warnings.map(w=>`<div class="note warning">${esc(w)}</div>`).join('')}<section class="card report-section"><div class="card-title"><h2>Primary outcome</h2><span class="badge">${primary.method} · n=${primary.n}</span></div><p>Vitamin D and pseudocapsule collagen fraction</p><div class="scores"><div class="score-box">Correlation<strong>${fmt(primary.coefficient,3)}</strong></div><div class="score-box">95% interval<strong style="font-size:20px">${primary.ci?primary.ci.map(v=>fmt(v,3)).join(' to '):'—'}</strong></div><div class="score-box">Two-sided p<strong>${pval(primary.p)}</strong></div></div>${primary.note?`<div class="note">${primary.note}</div>`:''}${scatter(primary.points,'Vitamin D (ng/mL)','Pseudocapsule collagen (%)')}<p class="small-text">${primary.ciMethod||''}${primary.pMethod?' · '+primary.pMethod:''}. Primary p-value is unadjusted.</p></section><section class="card report-section"><div class="card-title"><h2>Four-region comparison</h2><span class="badge">Complete participants: ${z.n}</span></div><p>${z.method==='anova'?'Repeated-measures ANOVA with Greenhouse–Geisser correction':'Friedman test'} · ${z.excluded} excluded for missing regions.</p><div class="scores"><div class="score-box">Statistic<strong>${fmt(z.statistic,3)}</strong></div><div class="score-box">p-value<strong>${pval(z.p)}</strong></div><div class="score-box">${z.method==='anova'?'Partial η²':'Kendall’s W'}<strong>${fmt(z.partialEtaSquared??z.kendallW,3)}</strong></div></div><div class="note">${esc(z.note||'')}${z.epsilon!=null?' GG ε='+fmt(z.epsilon,3)+'.':''}</div>${pairedPlot(r.rows)}${z.posthoc.length?table(['Comparison','Mean difference (pp)','Test','Raw p','Holm p'],z.posthoc.map(x=>[x.regions.join(' − '),fmt(x.meanDifference,2),x.test,pval(x.p),pval(x.holmP)])):''}</section><section class="card"><h2>Descriptive statistics and normality</h2><p class="small-text">Q1–Q3 uses linear percentiles. Shapiro–Wilk is unavailable for fewer than 3 observations or constant values.</p>${table(['Variable','n','Missing','Mean ± SD','Median [Q1, Q3]','Shapiro W','Shapiro p'],Object.entries(r.descriptive).map(([k,v])=>[label(k),v.n,v.missing,`${fmt(v.mean)} ± ${fmt(v.sd)}`,`${fmt(v.median)} [${fmt(v.q1)}, ${fmt(v.q3)}]`,fmt(v.shapiroW,3),pval(v.shapiroP)]))}<details><summary>Distribution plots</summary><label>Variable<select id="distribution-variable">${Object.keys(r.descriptive).map(k=>`<option value="${k}">${label(k)}</option>`).join('')}</select></label><div id="distribution-chart"></div><p class="small-text">Values are displayed in participant order to reveal spread and unusual observations.</p></details></section><section class="card"><h2>Categorical summaries</h2>${table(['Variable','Category','n','% of nonmissing','Missing'],Object.entries(r.categorical).flatMap(([k,v])=>Object.entries(v.counts).map(([c,n])=>[label(k),esc(c),n,fmt(100*n/v.n),v.missing])))}</section><section class="card"><h2>Secondary correlations</h2><p class="small-text">Pairwise complete cases. Holm correction covers all available secondary correlations in this report; primary association is excluded from this family.</p>${table(['Variables','n','Coefficient','95% interval','Raw p','Holm p'],r.correlations.slice(1).map(x=>[`${label(x.x)} × ${label(x.y)}`,x.n,fmt(x.coefficient,3),x.ci?x.ci.map(v=>fmt(v,3)).join(' to '):'—',pval(x.p),pval(x.holmP)]))}</section><section class="card"><h2>Agreement between pathologists</h2><p class="small-text">ICC(A,1): two-way absolute agreement, single measurement. Region-level A/B pairs. Limits of agreement use A−B percentage points; ICC intervals use a 1000-resample percentile bootstrap when n≥6.</p>${table(['Region','Paired n','ICC(A,1)','95% interval','Mean difference (pp)','Agreement limits (pp)'],r.agreement.map(x=>[x.region,x.n,fmt(x.icc,3),x.ci?x.ci.map(v=>fmt(v,3)).join(' to '):'—',fmt(x.bias,2),x.limits?x.limits.map(v=>fmt(v,2)).join(' to '):'—']))}<details><summary>Bland–Altman plots</summary>${r.agreement.map(x=>`<h3>${x.region}</h3>${scatter(x.points,'Mean of A and B (%)','A − B (percentage points)')}`).join('')}</details></section><section class="card"><h2>Exploratory subgroups</h2><p class="small-text">Outcome: pseudocapsule collagen fraction. Kruskal–Wallis tests require at least two observations per group; small subgroups remain descriptive. Holm correction covers the available subgroup tests.</p>${r.subgroups.map(s=>`<h3>${label(s.group)}</h3>${table(['Group','n','Median [Q1, Q3]'],Object.entries(s.summaries).map(([k,v])=>[esc(k),v.n,`${fmt(v.median)} [${fmt(v.q1)}, ${fmt(v.q3)}]`]))}<p class="small-text">Raw p: ${pval(s.p)} · Holm p: ${pval(s.holmP)}</p>`).join('')}</section><section class="card"><h2>Exploratory regression</h2><p>Outcome: ${label(g.outcome)} · n=${g.n} · ${g.excluded} excluded</p><div class="note warning">${esc(g.note)}</div>${g.coefficients?`<p>R² ${fmt(g.rSquared,3)} · Adjusted R² ${fmt(g.adjustedRSquared,3)} · Condition number ${fmt(g.conditionNumber,1)}</p>${table(['Term','Estimate','SE','95% interval','p'],g.coefficients.map(c=>[label(c.term),fmt(c.estimate,3),fmt(c.se,3),c.ci.map(v=>fmt(v,3)).join(' to '),pval(c.p)]))}${scatter(g.fitted.map((v,i)=>[v,g.residuals[i]]),'Fitted value','Residual')}<p class="small-text">Residual Shapiro–Wilk p: ${pval(g.residualNormality.shapiroP)}. This is an association model, not a clinical prediction tool.</p>`:''}</section><footer>Research outputs require review against the agreed study analysis plan. Image validity, field selection and questionnaire source are not established by a successful calculation.</footer>`;$('#print-report').onclick=()=>window.print();$('#export-analysis').onclick=()=>download('thesis-analysis.json',JSON.stringify(r,null,2));$('#export-master').onclick=()=>{const rows=r.rows;const keys=rows.length?Object.keys(rows[0]):['id'];const quote=v=>{let s=String(v??'');if(/^[=+@-]/.test(s)&&typeof v==='string')s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download('thesis-master-reviewer-'+r.reviewer+'.csv','\ufeff'+[keys,...rows.map(row=>keys.map(k=>row[k]))].map(a=>a.map(quote).join(',')).join('\r\n'),'text/csv')};$('#export-charts').onclick=()=>{const html='<!doctype html><meta charset="utf-8"><title>Study charts</title><style>body{font-family:Arial;max-width:900px;margin:40px auto}svg{width:100%;margin:20px 0}</style><h1>Study charts</h1><p>'+esc(new Date(r.generated).toLocaleString())+'</p>'+$$('#analysis-result svg').map(s=>s.outerHTML).join('');download('study-charts.html',html,'text/html')};const dist=()=>{const key=$('#distribution-variable').value;$('#distribution-chart').innerHTML=scatter(r.rows.map((x,i)=>[i+1,x[key]]).filter(p=>p[1]!=null),'Participant order',label(key))};$('#distribution-variable').onchange=dist;dist()}

function methodsPage(){$('#app').innerHTML=heading('REPRODUCIBILITY','Methods & backup','Keep the source data, calculation rules and review history together.')+`<div class="two-col"><section class="card"><h2>Back up your study</h2><p>A backup includes participant records, original images, colour masks, settings and saved record history.</p><button class="button primary" id="download-backup">Download complete backup</button><div class="note">Records and images are saved in this browser only. Download backups regularly. Clearing site data, private browsing, changing browser, or changing the website address can remove access to your study. Study records are not uploaded to GitHub. Internet access is required to download the calculation engine on first use.</div><div class="toolbar"><a class="button" href="#" data-export="master.csv">Master CSV · reviewer A</a><a class="button" href="#" data-export="measurements.csv">All field measurements</a></div><details><summary>Restore a backup</summary><p class="small-text">Restore is available only when the participant register is empty, so existing records cannot be overwritten. Restore supports ZIP files up to 90 MB (400 MB unpacked). Keep backups within this limit.</p><label>Backup ZIP<input id="restore-file" type="file" accept=".zip"></label><button class="button" id="restore-backup">Restore into empty study</button></details></section><section class="card"><h2>Current study rules</h2><div class="region-line"><span>Regions</span><strong>4</strong></div><div class="region-line"><span>Recruitment target</span><strong>32</strong></div><div class="region-line"><span>PBAC study threshold</span><strong>&gt;100</strong></div><div class="region-line"><span>Flooding score</span><strong>1 / episode</strong></div><div class="region-line"><span>Collagen denominator</span><strong>Eligible tissue</strong></div><div class="region-line"><span>Statistical unit</span><strong>Participant</strong></div></section></div><section class="card"><h2>Measurement and analysis rules</h2><p><strong>Image analysis.</strong> HSV colour thresholds classify blue and pink pixels. Background and drawn exclusions are removed; other eligible tissue remains in the denominator. Original image resolution is used for counting. This method needs pilot calibration and comparison against ImageJ/pathologist measurements. It is not automatic histological recognition or stain deconvolution.</p><p><strong>Aggregation.</strong> Within each region and reviewer, measurements use eligible-area weighting when every field has a pixel count. Otherwise all fields receive equal weight, with a visible warning. Use consistent acquisition settings and non-overlapping fields.</p><p><strong>Questionnaires.</strong> PBAC follows your supplied chart. Empty days are not assumed to be zero; the cycle must be marked complete. UFS-QOL uses official item numbering, standard original six-domain mapping and 0–100 transformations. It does not reproduce protected questionnaire wording. Only confirmed official-form scores enter the existing UFS-QOL analyses. Appendix D responses are stored separately, with raw domain sums and a composite (37–185). Incomplete domains are not scored or imputed. Appendix D scores and responses are included in the master CSV.</p><p><strong>Statistical choices.</strong> The researcher selects Pearson/Spearman and repeated-measures ANOVA/Friedman. Complete cases are used per analysis. ANOVA uses Greenhouse–Geisser correction; Friedman reports a within-participant permutation p-value. Secondary correlations, region post-hoc comparisons and subgroup comparisons have separate Holm correction families. Regression is exploratory and uses conventional OLS confidence intervals.</p><p><strong>Study categories.</strong> Vitamin D: &lt;20, 20 to &lt;30, and ≥30 ng/mL; these implement the protocol’s study categories. Largest fibroid dimension: ≤5 or &gt;5 cm. Volume uses an ellipsoid estimate when three perpendicular dimensions are available.</p><p><strong>Not yet defined.</strong> Sampling density, a fibrosis grading scale and optional VDR/TGFβ1 immunohistochemistry scoring are not specified. The app does not invent grades or IHC results. Physical area needs pixel calibration and is not reported by this version.</p><details><summary>Sources and calculation documentation</summary><ul><li><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10071864/" target="_blank" rel="noopener">UFS-QOL scoring manual, Appendix B</a></li><li><a href="https://www.sirfoundation.org/research/uterine-fibroid-symptom-health-related-quality-of-life-questionnaire-ufs-qol/" target="_blank" rel="noopener">Official UFS-QOL access and permissions</a></li><li><a href="https://docs.scipy.org/doc/scipy/reference/stats.html" target="_blank" rel="noopener">SciPy statistical methods</a></li><li><a href="https://www.statsmodels.org/stable/regression.html" target="_blank" rel="noopener">Statsmodels regression</a></li><li>User-provided thesis protocol and PBAC chart.</li></ul></details></section><section class="card"><h2>Recent saved history</h2><p class="small-text">Each save keeps the complete prior sequence of record versions in the backup. Up to 100 recent actions appear here.</p><div id="audit-list">Loading history…</div></section>`;$('#download-backup').onclick=()=>downloadURL('/api/backup');$('#restore-backup').onclick=async()=>{try{const file=$('#restore-file').files[0];if(!file)throw Error('Select a backup ZIP.');if(file.size>90e6)throw Error('This version restores ZIP backups up to 90 MB.');if(state.participants.length)throw Error('Restore requires an empty participant register.');if(!confirm('Restore participant records and images from this backup?'))return;await api('restore',{backup:await fileData(file)});state.participants=await api('participants');state.selected=state.participants[0]?.id;state.report=null;toast('Backup restored');render()}catch(e){toast(e.message)}};api('audit').then(rows=>{if($('#audit-list'))$('#audit-list').innerHTML=table(['Saved','Action','Study ID'],rows.map(r=>[esc(new Date(r.date).toLocaleString()),esc(r.action),esc(r.participant)]))}).catch(e=>toast(e.message))}

// Optional browser agent integration; all actions reuse the visible app state.
if(document.modelContext?.registerTool){const life=new AbortController();const reg=t=>Promise.resolve(document.modelContext.registerTool(t,{signal:life.signal})).catch(()=>{});reg({name:'read_study_summary',title:'Read study summary',description:'Read the locally saved participant count and completion totals without changing records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({participants:state.participants.length,fourRegions:state.participants.filter(p=>regions.every(r=>aggregate(p,r))).length})});reg({name:'open_participant_workspace',title:'Open participant workspace',description:'Navigate to an existing participant tissue workspace. Does not change saved data.',inputSchema:{type:'object',properties:{studyId:{type:'string'}},required:['studyId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(typeof input?.studyId!=='string'||!state.participants.some(p=>p.id===input.studyId))throw Error('Unknown study ID');if(state.dirty)throw Error('Save or discard the current draft first');state.selected=input.studyId;navigate('tissue');return {studyId:state.selected,view:state.view}}});window.addEventListener('pagehide',()=>life.abort())}

document.addEventListener('click',e=>{const a=e.target.closest('[data-export]');if(a){e.preventDefault();downloadURL(a.dataset.export)}});

const appendixDomains=[
 ['Symptom Severity',['Heavy menstrual bleeding','Passing blood clots','Pelvic pain','Pelvic pressure','Abdominal bloating','Back pain','Fatigue due to bleeding','Interference with daily routine']],
 ['Concern',['Worry about fibroid growth','Concern about fertility','Concern about hysterectomy','Concern about recurrence','Concern about anemia','Concern about sexual health','Concern about overall health']],
 ['Activities',['Limitation in household work','Limitation in professional work','Limitation in social activities','Limitation in travel','Limitation in exercise','Limitation in leisure activities']],
 ['Energy/Mood',['Feeling tired','Feeling irritable','Feeling anxious','Feeling depressed','Feeling low energy','Difficulty concentrating']],
 ['Control',['Ability to control bleeding','Ability to control pain','Ability to control fatigue','Ability to control mood','Ability to control daily routine']],
 ['Sexual Function',['Pain during intercourse','Reduced sexual desire','Reduced sexual satisfaction','Avoidance of sexual activity','Impact on partner relationship']]
];
function appendixForm(){
 const u=participant().appendixD||{}, answers=u.answers||Array(37).fill(null);let index=0;
 $('#question-content').innerHTML=`<section class="card"><div class="card-title"><h2>Appendix D · Uterine Fibroid Quality of Life Questionnaire (UFS-QOL)</h2><span class="badge">37 items · 6 domains</span></div><p>Please read each statement carefully and mark your response.</p><div class="note">1 = Not at all · 2 = A little · 3 = Moderately · 4 = Quite a bit · 5 = Extremely</div><form id="appendix-form">${input('Assessment date','date',u.date,'date','required')}${appendixDomains.map(([name,questions])=>`<fieldset class="appendix-domain"><legend>${name} Domain</legend>${questions.map(question=>{const i=index++;return `<label class="appendix-question"><span><span class="region-num">${i+1}.</span>${question}</span><select data-appendix-item="${i}" aria-label="Item ${i+1}: ${question}"><option value="">Unanswered</option>${['Not at all','A little','Moderately','Quite a bit','Extremely'].map((text,n)=>`<option value="${n+1}" ${answers[i]===n+1?'selected':''}>${n+1} — ${text}</option>`).join('')}</select></label>`}).join('')}</fieldset>`).join('')}<h3>Scoring</h3><p class="small-text">Each item is scored 1–5. Domain scores are calculated separately. Higher scores indicate greater impairment. The composite is the sum of the six domain scores, following the supplied Appendix D. All items in a domain must be answered for its score; all 37 are needed for the composite.</p><div id="appendix-scores" class="scores" aria-live="polite"></div><p id="appendix-progress" class="small-text"></p><button class="button primary">Save Appendix D responses</button></form></section>`;
 const f=$('#appendix-form'), read=()=>({date:f.elements.date.value,answers:$$('[data-appendix-item]').map(el=>num(el.value)),version:'Appendix D supplied study form'});
 const calc=()=>{const a=read().answers;let offset=0,total=0,complete=true;const boxes=appendixDomains.map(([name,questions])=>{const values=a.slice(offset,offset+=questions.length),count=values.filter(v=>v!==null).length,score=count===values.length?values.reduce((s,v)=>s+v,0):null;if(score===null)complete=false;else total+=score;return `<div class="score-box"><span>${name}</span><strong>${score??'—'}</strong><small>${count}/${values.length} answered · range ${values.length}–${values.length*5}</small></div>`});$('#appendix-scores').innerHTML=boxes.join('')+`<div class="score-box"><span>Composite</span><strong>${complete?total:'—'}</strong><small>Range 37–185</small></div>`;$('#appendix-progress').textContent=`${a.filter(v=>v!==null).length} of 37 answered. Partial responses can be saved.`};
 f.oninput=()=>{dirty();calc()};f.onchange=()=>{dirty();calc()};f.onsubmit=async e=>{e.preventDefault();try{const p=structuredClone(participant());p.appendixD=read();await save(p);render()}catch(e){toast(e.message)}};calc();
}
